function validateState(state) {
  if (state === null || typeof state !== 'object' || Array.isArray(state)) {
    throw new TypeError('state must be an object');
  }
  for (const key of ['value', 'min', 'max', 'step']) {
    if (typeof state[key] !== 'number' || !Number.isFinite(state[key])) {
      throw new TypeError(key + ' must be finite');
    }
  }
  if (state.min > state.max || state.step <= 0 ||
      state.value < state.min || state.value > state.max) {
    throw new RangeError('invalid numeric state');
  }
}

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function rounded(value) {
  return Math.round(value * 1e12) / 1e12;
}

function reduceNumericInput(state, action) {
  validateState(state);
  if (action === null || typeof action !== 'object' || Array.isArray(action)) {
    throw new TypeError('action must be an object');
  }

  let value = state.value;
  if (action.type === 'input') {
    if (typeof action.text !== 'string' || !/^-?\d+(?:\.\d+)?$/.test(action.text)) {
      throw new TypeError('text must be an ordinary decimal');
    }
    const parsed = Number(action.text);
    if (!Number.isFinite(parsed)) {
      throw new TypeError('text is outside the finite numeric range');
    }
    value = clamp(parsed, state.min, state.max);
  } else if (action.type === 'key') {
    if (action.key === 'ArrowUp') {
      value = clamp(rounded(value + state.step), state.min, state.max);
    } else if (action.key === 'ArrowDown') {
      value = clamp(rounded(value + state.step), state.min, state.max);
    }
  } else {
    throw new TypeError('unknown action type');
  }

  return { value, min: state.min, max: state.max, step: state.step };
}

module.exports = { reduceNumericInput };

