'use strict';

const assert = require('node:assert/strict');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api).sort(), ['reduceNumericInput']);
const { reduceNumericInput } = api;

for (const state of [null, [], { value: 1, min: 0, max: 2 }, { value: NaN, min: 0, max: 2, step: 1 }, { value: 1, min: 0, max: Infinity, step: 1 }, { value: 1, min: 0, max: 2, step: '1' }]) {
  assert.throws(() => reduceNumericInput(state, { type: 'key', key: 'x' }), TypeError);
}
for (const state of [
  { value: 1, min: 2, max: 0, step: 1 },
  { value: -1, min: 0, max: 2, step: 1 },
  { value: 3, min: 0, max: 2, step: 1 },
  { value: 1, min: 0, max: 2, step: 0 },
  { value: 1, min: 0, max: 2, step: -1 }
]) {
  assert.throws(() => reduceNumericInput(state, { type: 'key', key: 'x' }), RangeError);
}

const state = { value: 0.2, min: 0, max: 1, step: 0.1 };
for (const action of [null, [], 'action']) {
  assert.throws(() => reduceNumericInput(state, action), TypeError);
}
assert.throws(() => reduceNumericInput(state, { type: 'unknown' }), TypeError);

const up = reduceNumericInput(state, { type: 'key', key: 'ArrowUp' });
assert.deepStrictEqual(up, { value: 0.3, min: 0, max: 1, step: 0.1 });
assert.notStrictEqual(up, state);
assert.deepStrictEqual(state, { value: 0.2, min: 0, max: 1, step: 0.1 });
assert.deepStrictEqual(reduceNumericInput({ value: 0.95, min: 0, max: 1, step: 0.1 }, { type: 'key', key: 'ArrowUp' }), { value: 1, min: 0, max: 1, step: 0.1 });
assert.deepStrictEqual(reduceNumericInput({ value: 0.05, min: 0, max: 1, step: 0.1 }, { type: 'key', key: 'ArrowDown' }), { value: 0, min: 0, max: 1, step: 0.1 });

const unchanged = reduceNumericInput(state, { type: 'key', key: 'Enter' });
assert.deepStrictEqual(unchanged, state);
assert.notStrictEqual(unchanged, state);

for (const text of ['', ' ', '+1', '.5', '1.', '1e2', '--1', 'Infinity', 'NaN', 2]) {
  assert.throws(() => reduceNumericInput(state, { type: 'input', text }), TypeError);
  assert.deepStrictEqual(state, { value: 0.2, min: 0, max: 1, step: 0.1 });
}
assert.deepStrictEqual(reduceNumericInput(state, { type: 'input', text: '0.75' }), { value: 0.75, min: 0, max: 1, step: 0.1 });
assert.deepStrictEqual(reduceNumericInput(state, { type: 'input', text: '-20' }), { value: 0, min: 0, max: 1, step: 0.1 });
assert.deepStrictEqual(reduceNumericInput(state, { type: 'input', text: '20' }), { value: 1, min: 0, max: 1, step: 0.1 });
assert.deepStrictEqual(reduceNumericInput(state, { type: 'input', text: '01.50' }), { value: 1, min: 0, max: 1, step: 0.1 });
assert.throws(() => reduceNumericInput(state, { type: 'input', text: '9'.repeat(400) }), TypeError);

